def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a grid with default value -1
    grid = [[-1] * N for _ in range(N)]

    # Populate the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize DP table
    dp = [[[float('-inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    # Fill the DP table
    for x in range(N):
        for y in range(N):
            for z in range(N):
                if x == 0 and y == 0 and z == 0:
                    continue
                if x > 0:
                    dp[x][y][z] = max(dp[x][y][z], dp[x-1][y][z] + grid[x][y])
                if y > 0:
                    dp[x][y][z] = max(dp[x][y][z], dp[x][y-1][z] + grid[x][y])
                if z < N and z != x and z != y:
                    dp[x][y][z] = max(dp[x][y][z], dp[x][y][z+1] + grid[x][y])

    # Find the maximum sum of values collected on two paths
    max_sum = float('-inf')
    for x in range(N):
        for y in range(N):
            if x == 0 and y == 0:
                continue
            max_sum = max(max_sum, dp[x][y][x+y])

    return max_sum

def find_number_combinations():
    """
    Generates all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.
    """
    result = []

    def is_valid_num(num):
        return len(set(str(num))) == len(str(num)) and 1 <= num <= 999

    for i in range(1, 1000 // 3 + 1):
        if is_valid_num(i) and is_valid_num(2 * i) and is_valid_num(3 * i):
            result.append((i, 2 * i, 3 * i))

    return sorted(result)

