def max_product(num_str: str, N: int, K: int) -> int:
    """
    Finds the maximum product that can be obtained by inserting K multiplication signs into the number string.

    :param num_str: str - A string representing the number string.
    :param N: int - An integer representing the length of the number string.
    :param K: int - An integer representing the number of multiplication signs to insert.
    :return: int - The maximum product.
    """
    if K == 0:
        return int(num_str)

    nums = list(map(int, num_str))
    n = len(nums)

    # dp[i][j] represents the maximum product we can get by placing j multiplication signs in the first i digits
    dp = [[0] * (K + 1) for _ in range(n + 1)]

    def multiply(a, b):
        return a * b

    # Initialize the dp array
    for i in range(1, n + 1):
        dp[i][0] = int(''.join(map(str, nums[:i])))

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(1, min(i, K + 1)):
            for l in range(1, i):
                dp[i][j] = max(dp[i][j], dp[l][j - 1] * multiply(int(''.join(map(str, nums[l:i]))), int(''.join(map(str, nums[:l])))))

    return dp[n][K]

